//! Every code this crate emits has a catalogue entry that says what it means and how to repair it.
//!
//! The catalogues are generated by the crate's `diagnostic_catalogue!` together with the
//! exhaustive match that maps a refusal to its entry, so a variant with no entry does not compile.
//! What these cases hold is the rest: the keys form the code space the published reference and the
//! coverage readers expect, each once, and no text is empty.
//! `website/docs/reference/diagnostics.md` is rendered from them.

use ess_compiler::diagnostic::CatalogueEntry;
use ess_conformance::authored::Cause;
use ess_conformance::history::HistoryRefusal;
use ess_conformance::mutate::MutateCode;
use ess_conformance::synthesize::RefusalCause;
use std::collections::BTreeSet;
use std::fmt::Debug;

fn said<K: Debug>(entries: &[CatalogueEntry<K>]) {
    for entry in entries {
        assert!(
            !entry.meaning.trim().is_empty(),
            "{:?} has no meaning",
            entry.key
        );
        assert!(
            !entry.repair.trim().is_empty(),
            "{:?} has no repair",
            entry.key
        );
    }
}

fn numbered(entries: &[CatalogueEntry<u16>], last: u16) {
    let numbers: Vec<u16> = entries.iter().map(|entry| entry.key).collect();
    let expected: Vec<u16> = (1..=last).collect();
    assert_eq!(
        numbers, expected,
        "catalogued once each, in code order, with no gap"
    );
    said(entries);
}

#[test]
fn author_codes_run_from_001_to_040() {
    assert_eq!(Cause::FAMILY, "AUTHOR");
    numbered(Cause::CATALOGUE, 40);
}

#[test]
fn synth_codes_run_from_001_to_019() {
    assert_eq!(RefusalCause::FAMILY, "SYNTH");
    numbered(RefusalCause::CATALOGUE, 19);
}

#[test]
fn mutate_codes_run_from_001_to_005_and_match_every_mutate_code() {
    assert_eq!(ess_conformance::mutate::FAMILY, "MUTATE");
    numbered(MutateCode::CATALOGUE, 5);
    for code in MutateCode::ALL {
        assert_eq!(code.code().number, code.catalogue_entry().key, "{code:?}");
    }
    assert_eq!(MutateCode::ALL.len(), MutateCode::CATALOGUE.len());
}

#[test]
fn the_fifteen_dotted_history_refusals_are_catalogued_once_each() {
    let names: BTreeSet<&str> = HistoryRefusal::CATALOGUE
        .iter()
        .map(|entry| entry.key)
        .collect();
    assert_eq!(names.len(), 15, "{names:?}");
    assert_eq!(names.len(), HistoryRefusal::CATALOGUE.len(), "a name twice");
    for name in &names {
        assert!(name.starts_with("history."), "{name}");
    }
    said(HistoryRefusal::CATALOGUE);
    let refusal = HistoryRefusal::NoClients;
    assert_eq!(refusal.code(), refusal.catalogue_entry().key);
}
